cat << 'EOF' > /app/add_legend.py
import json
import textwrap

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

nodes = data['pipeline_nodes']['data']
edges = data['pipeline_edges']['data']

def wrap_text(text, width=20):
    return "\\n".join(textwrap.wrap(text, width=width))

dot_code = [
    'digraph Pipeline {',
    '  rankdir=LR;',
    '  splines=polyline;',
    '  nodesep=0.7;',
    '  ranksep=1.0;',
    '  pad=0.5;',
    '  fontname="Helvetica";',
    '  label="Kubernetes Multi-Environment Deployment Pipeline";',
    '  labelloc="t";',
    '  fontsize=24;',
    '  fontweight="bold";',
    '  node [fontname="Helvetica", fontsize=11, penwidth=1.5, margin="0.2,0.1", style="rounded,filled"];',
    '  edge [fontname="Helvetica", fontsize=10, penwidth=2.0];',
]

lanes = ['dev', 'staging', 'canary', 'production', 'global']
lane_colors = {
    'dev': ('#E6F0FA', '#4C72B0', 'Dev Environment'),
    'staging': ('#F2EEFA', '#8172B3', 'Staging Environment'),
    'canary': ('#FDF0E6', '#DD8452', 'Canary Environment'),
    'production': ('#EEF7F0', '#55A868', 'Production Environment'),
    'global': ('#F5F5F5', '#937860', 'Global / Operations')
}

node_types = {
    'action': {'shape': 'box', 'fillcolor': '#D9E8F5', 'color': '#4C72B0'},
    'check': {'shape': 'box', 'fillcolor': '#E5F5E0', 'color': '#55A868'},
    'decision': {'shape': 'diamond', 'fillcolor': '#FFF3E0', 'color': '#DD8452', 'margin': '0,0'},
    'hpa_decision': {'shape': 'hexagon', 'fillcolor': '#EFE5FD', 'color': '#8172B3'},
    'rollback': {'shape': 'box', 'fillcolor': '#FDE0E0', 'color': '#C44E52'},
    'terminal': {'shape': 'ellipse', 'fillcolor': '#D0F0D0', 'color': '#2E8B57', 'penwidth': '2.5'},
    'hpa_action': {'shape': 'note', 'fillcolor': '#FFF5EB', 'color': '#DD8452'}
}

# Legend subgraph
legend = """
  subgraph cluster_legend {
    label="Legend";
    style="rounded";
    color="#999999";
    fontname="Helvetica";
    fontsize=12;
    rank=sink;

    L_action [label="Action", shape=box, fillcolor="#D9E8F5", color="#4C72B0", style="rounded,filled"];
    L_check [label="Health/Metric Check", shape=box, fillcolor="#E5F5E0", color="#55A868", style="rounded,filled"];
    L_decision [label="Health Gate / Decision", shape=diamond, fillcolor="#FFF3E0", color="#DD8452", style="rounded,filled", margin="0,0"];
    L_hpa [label="HPA Scaling Check", shape=hexagon, fillcolor="#EFE5FD", color="#8172B3", style="rounded,filled"];
    L_rollback [label="Rollback Node", shape=box, fillcolor="#FDE0E0", color="#C44E52", style="rounded,filled"];
    L_edge_fwd [shape=none, label="Forward Flow", fontcolor="#4C72B0"];
    L_edge_rbk [shape=none, label="Rollback Path", fontcolor="#C44E52"];
    L_edge_bg [shape=none, label="Blue-Green Cutover", fontcolor="#2E8B57"];
    L_edge_hpa [shape=none, label="HPA Trigger", fontcolor="#8172B3"];

    { rank=same; L_action; L_check; L_decision; L_hpa; L_rollback }
    { rank=same; L_edge_fwd; L_edge_rbk; L_edge_bg; L_edge_hpa }

    L_action -> L_edge_fwd [style=invis];
  }
"""
dot_code.append(legend)

dot_code.append('  // Invisible nodes to force cluster order')
for lane in lanes:
    dot_code.append(f'  align_{lane} [shape=point, style=invis, width=0, height=0];')
for i in range(len(lanes)-1):
    dot_code.append(f'  align_{lanes[i]} -> align_{lanes[i+1]} [style=invis, weight=1000];')

nodes_by_lane = {lane: [] for lane in lanes}
for n in nodes:
    nodes_by_lane[n.get('lane', 'global')].append(n)

for lane in lanes:
    bg, fg, title = lane_colors[lane]
    dot_code.append(f'  subgraph cluster_{lane} {{')
    dot_code.append(f'    label="{title}";')
    dot_code.append(f'    style="filled,rounded";')
    dot_code.append(f'    fillcolor="{bg}";')
    dot_code.append(f'    color="{fg}";')
    dot_code.append(f'    penwidth=2.0;')
    dot_code.append(f'    fontsize=14;')
    dot_code.append(f'    fontcolor="{fg}";')
    dot_code.append(f'    labeljust="c";')

    dot_code.append(f'    align_{lane};')

    for n in nodes_by_lane[lane]:
        nid = n['id']
        ntype = n['type']
        label = n['label']

        extra = []
        if 'cpu_threshold_pct' in n:
            extra.append(f"CPU > {n['cpu_threshold_pct']}%")
        if 'mem_threshold_pct' in n:
            extra.append(f"Mem > {n['mem_threshold_pct']}%")
        if 'error_rate_threshold_pct' in n:
            extra.append(f"Err > {n['error_rate_threshold_pct']}%")
        if 'p99_latency_ms_threshold' in n:
            extra.append(f"p99 > {n['p99_latency_ms_threshold']}ms")
        if 'traffic_pct' in n:
            extra.append(f"Traffic: {n['traffic_pct']}%")

        if extra:
            label += "\\n(" + " | ".join(extra) + ")"

        wrapped_label = wrap_text(label, 20)

        attrs = node_types.get(ntype, node_types['action']).copy()
        if attrs['shape'] == 'diamond':
            wrapped_label = wrap_text(label, 15)

        attr_str = f'label="{wrapped_label}"'
        for k, v in attrs.items():
            attr_str += f', {k}="{v}"'

        dot_code.append(f'    "{nid}" [{attr_str}];')

    dot_code.append('  }')

edge_styles = {
    'forward': {'color': '#4C72B0', 'style': 'solid'},
    'rollback': {'color': '#C44E52', 'style': 'dashed', 'penwidth': '2.5', 'fontcolor': '#C44E52'},
    'hpa_branch': {'color': '#8172B3', 'style': 'dotted', 'penwidth': '2.0', 'fontcolor': '#8172B3'},
    'blue_green': {'color': '#2E8B57', 'style': 'bold', 'penwidth': '3.0', 'fontcolor': '#2E8B57'}
}

# Add Edges
for e in edges:
    src = e['from']
    dst = e['to']
    etype = e['type']
    label = e.get('label', '')

    attrs = edge_styles.get(etype, edge_styles['forward']).copy()

    # Increase weight for forward edges
    if etype == 'forward':
        attrs['weight'] = '10'
    elif etype == 'blue_green':
        attrs['weight'] = '10'

    if label:
        wrapped_label = wrap_text(label, 15)
        attrs['label'] = wrapped_label

    attr_str = ', '.join([f'{k}="{v}"' for k, v in attrs.items()])
    dot_code.append(f'  "{src}" -> "{dst}" [{attr_str}];')

# Add dummy edges for legend text to force colors
dot_code.append('  L_edge_fwd -> L_edge_rbk [style=invis];')
dot_code.append('  L_edge_rbk -> L_edge_bg [style=invis];')
dot_code.append('  L_edge_bg -> L_edge_hpa [style=invis];')

dot_code.append('}')

with open('/app/pipeline.dot', 'w') as f:
    f.write('\n'.join(dot_code))
